package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme that applies the specified overrides.
// Colors, sizes, fonts, and icons can be customized. Values not present in the JSON
// will fall back to the default theme.
// Supports variant-specific colors via "Colors-dark" and "Colors-light" keys.
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// See FromJSON for details on the JSON schema.
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var jsonData map[string]interface{}
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&jsonData); err != nil {
		return DarkTheme(), err
	}

	return &jsonTheme{
		data:    jsonData,
		fallback: DarkTheme(),
	}, nil
}

type jsonTheme struct {
	data     map[string]interface{}
	fallback fyne.Theme
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	var variantKey string
	if variant == fyne.VariantDark {
		variantKey = "Colors-dark"
	} else if variant == fyne.VariantLight {
		variantKey = "Colors-light"
	}

	if variantKey != "" {
		if variantColors, ok := t.data[variantKey].(map[string]interface{}); ok {
			if hexStr, ok := variantColors[string(name)].(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					return c
				}
			}
		}
	}

	// Check generic colors
	if colors, ok := t.data["Colors"].(map[string]interface{}); ok {
		if hexStr, ok := colors[string(name)].(string); ok {
			if c, err := parseHexColor(hexStr); err == nil {
				return c
			}
		}
	}

	// Fallback to default theme
	return t.fallback.Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	if fonts, ok := t.data["Fonts"].(map[string]interface{}); ok {
		var fontKey string
		if style.Bold && style.Italic {
			fontKey = "boldItalic"
		} else if style.Bold {
			fontKey = "bold"
		} else if style.Monospace {
			fontKey = "monospace"
		} else {
			fontKey = "regular"
		}

		if uriStr, ok := fonts[fontKey].(string); ok {
			if uri, err := storage.ParseURI(uriStr); err == nil {
				if res, err := storage.LoadResourceFromURI(uri); err == nil {
					return res
				}
			}
		}
	}

	return t.fallback.Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if icons, ok := t.data["Icons"].(map[string]interface{}); ok {
		if uriStr, ok := icons[string(name)].(string); ok {
			if uri, err := storage.ParseURI(uriStr); err == nil {
				if res, err := storage.LoadResourceFromURI(uri); err == nil {
					return res
				}
			}
		}
	}

	return t.fallback.Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if sizes, ok := t.data["Sizes"].(map[string]interface{}); ok {
		if val, ok := sizes[string(name)]; ok {
			// Handle both float64 (from JSON) and direct float32
			switch v := val.(type) {
			case float64:
				return float32(v)
			case float32:
				return v
			}
		}
	}

	return t.fallback.Size(name)
}

// parseHexColor parses a hex color string and returns a color.Color.
// Supports formats: #rgb, #rgba, #rrggbb, #rrggbbaa (with or without # prefix)
// Also supports 3, 4, 6, and 8 digit hex without #
func parseHexColor(hex string) (color.Color, error) {
	// Remove # prefix if present
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	a = 0xff // Default alpha is fully opaque

	switch len(hex) {
	case 3:
		// RGB format: expand each digit
		if val, err := strconv.ParseUint(hex, 16, 16); err == nil {
			r = uint8((val >> 8) & 0xf)
			r = r<<4 | r
			g = uint8((val >> 4) & 0xf)
			g = g<<4 | g
			b = uint8(val & 0xf)
			b = b<<4 | b
		} else {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
	case 4:
		// RGBA format: expand each digit
		if val, err := strconv.ParseUint(hex, 16, 16); err == nil {
			r = uint8((val >> 12) & 0xf)
			r = r<<4 | r
			g = uint8((val >> 8) & 0xf)
			g = g<<4 | g
			b = uint8((val >> 4) & 0xf)
			b = b<<4 | b
			a = uint8(val & 0xf)
			a = a<<4 | a
		} else {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
	case 6:
		// RRGGBB format
		if val, err := strconv.ParseUint(hex, 16, 32); err == nil {
			r = uint8((val >> 16) & 0xff)
			g = uint8((val >> 8) & 0xff)
			b = uint8(val & 0xff)
		} else {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
	case 8:
		// RRGGBBAA format
		if val, err := strconv.ParseUint(hex, 16, 64); err == nil {
			r = uint8((val >> 24) & 0xff)
			g = uint8((val >> 16) & 0xff)
			b = uint8((val >> 8) & 0xff)
			a = uint8(val & 0xff)
		} else {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
	default:
		return color.Transparent, fmt.Errorf("invalid hex color length: %s", hex)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

