package binding

import (
	"fmt"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// NewSprintf creates a formatted string binding that combines multiple data sources.
// The format string follows fmt.Sprintf conventions. When any source binding changes,
// the formatted output is automatically recalculated.
// Set() attempts to parse the string back using fmt.Sscanf.
//
// Since: 2.0
func NewSprintf(format string, b ...DataItem) String {
	if len(b) == 0 {
		return NewString()
	}

	s := &sprintfBinding{
		format: format,
		sources: b,
	}
	s.val = new(string)

	// Add listeners to all source bindings
	for _, source := range b {
		source.AddListener(NewDataListener(func() {
			s.updateValue()
		}))
	}

	// Initial value calculation
	s.updateValue()

	return s
}

// StringToStringWithFormat wraps a String binding with a format string.
// If the format is "%s" (identity), returns the original binding unchanged.
//
// Since: 2.0
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

type sprintfBinding struct {
	base

	format  string
	sources []DataItem
	val     *string
	lastErr error
}

func (s *sprintfBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	if s.lastErr != nil {
		return "", s.lastErr
	}

	if s.val == nil {
		return "", nil
	}
	return *s.val, nil
}

func (s *sprintfBinding) Set(str string) error {
	s.lock.Lock()
	defer s.lock.Unlock()

	// Parse the string back to individual values
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		values[i] = s.makeValuePointer(source)
	}

	_, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}

	// Set each source binding
	for i, source := range s.sources {
		if err := s.setSourceValue(source, values[i]); err != nil {
			return err
		}
	}

	return nil
}

func (s *sprintfBinding) updateValue() {
	s.lock.Lock()
	defer s.lock.Unlock()

	// Get values from all sources
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		val, err := s.getSourceValue(source)
		if err != nil {
			s.lastErr = err
			s.trigger()
			return
		}
		values[i] = val
	}

	s.lastErr = nil
	formatted := fmt.Sprintf(s.format, values...)
	*s.val = formatted
	s.trigger()
}

func (s *sprintfBinding) getSourceValue(source DataItem) (interface{}, error) {
	switch b := source.(type) {
	case Bool:
		return b.Get()
	case Float:
		return b.Get()
	case Int:
		return b.Get()
	case Rune:
		return b.Get()
	case String:
		return b.Get()
	case Bytes:
		return b.Get()
	case URI:
		u, err := b.Get()
		if err != nil {
			return nil, err
		}
		if u == nil {
			return "", nil
		}
		return u.String(), nil
	default:
		if untyped, ok := source.(Untyped); ok {
			return untyped.Get()
		}
		return nil, fmt.Errorf("unsupported binding type")
	}
}

func (s *sprintfBinding) setSourceValue(source DataItem, valuePtr interface{}) error {
	switch b := source.(type) {
	case Bool:
		if ptr, ok := valuePtr.(*bool); ok {
			return b.Set(*ptr)
		}
	case Float:
		if ptr, ok := valuePtr.(*float64); ok {
			return b.Set(*ptr)
		}
	case Int:
		if ptr, ok := valuePtr.(*int); ok {
			return b.Set(*ptr)
		}
	case Rune:
		if ptr, ok := valuePtr.(*rune); ok {
			return b.Set(*ptr)
		}
	case String:
		if ptr, ok := valuePtr.(*string); ok {
			return b.Set(*ptr)
		}
	case Bytes:
		// Bytes cannot be round-tripped through Sscanf
		return fmt.Errorf("cannot set Bytes binding from formatted string")
	case URI:
		if ptr, ok := valuePtr.(*string); ok {
			uri, err := storage.ParseURI(*ptr)
			if err != nil {
				return err
			}
			return b.Set(uri)
		}
	default:
		if untyped, ok := source.(Untyped); ok {
			// Try to extract the value from the pointer
			switch ptr := valuePtr.(type) {
			case *bool:
				return untyped.Set(*ptr)
			case *int:
				return untyped.Set(*ptr)
			case *float64:
				return untyped.Set(*ptr)
			case *string:
				return untyped.Set(*ptr)
			}
		}
	}
	return fmt.Errorf("type mismatch in formatted binding")
}

func (s *sprintfBinding) makeValuePointer(source DataItem) interface{} {
	switch source.(type) {
	case Bool:
		var v bool
		return &v
	case Float:
		var v float64
		return &v
	case Int:
		var v int
		return &v
	case Rune:
		var v rune
		return &v
	case String:
		var v string
		return &v
	case URI:
		var v string
		return &v
	default:
		// Default to string for Untyped and unknown types
		var v string
		return &v
	}
}

