func (s *sprintfBinding) setSourceValue(source DataItem, valuePtr interface{}) error {
	switch b := source.(type) {
	case Bool:
		if ptr, ok := valuePtr.(*bool); ok {
			return b.Set(*ptr)
		}
	case Float:
		if ptr, ok := valuePtr.(*float64); ok {
			return b.Set(*ptr)
		}
	case Int:
		if ptr, ok := valuePtr.(*int); ok {
			return b.Set(*ptr)
		}
	case Rune:
		if ptr, ok := valuePtr.(*rune); ok {
			return b.Set(*ptr)
		}
	case String:
		if ptr, ok := valuePtr.(*string); ok {
			return b.Set(*ptr)
		}
	case URI:
		if ptr, ok := valuePtr.(*string); ok {
			uri, err := storage.ParseURI(*ptr)
			if err != nil {
				return err
			}
			return b.Set(uri)
		}
	default:
		if untyped, ok := source.(Untyped); ok {
			// Try to extract the value from the pointer
			switch ptr := valuePtr.(type) {
			case *bool:
				return untyped.Set(*ptr)
			case *int:
				return untyped.Set(*ptr)
			case *float64:
				return untyped.Set(*ptr)
			case *string:
				return untyped.Set(*ptr)
			}
		}
	}
	return fmt.Errorf("type mismatch in formatted binding")
}

